import functools

def getMaxGridHappiness(m: int, n: int, introvertsCount: int, extrovertsCount: int) -> int:
    if n > m:
        m, n = n, m
    pow3 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow3[i] = pow3[i - 1] * 3
    full = pow3[n]

    def interact(a, b):
        if a == 0 or b == 0:
            return 0
        return (-30 if a == 1 else 20) + (-30 if b == 1 else 20)

    base = (0, 120, 40)

    @functools.lru_cache(None)
    def dp(pos, mask, inn, exn):
        if pos == m * n:
            return 0
        r, c = divmod(pos, n)
        up = mask // pow3[n - 1]
        left = mask % 3 if c > 0 else 0
        best = -10 ** 9
        for choice in (0, 1, 2):
            if choice == 1 and inn == 0:
                continue
            if choice == 2 and exn == 0:
                continue
            gain = base[choice]
            gain += interact(choice, up if r > 0 else 0)
            gain += interact(choice, left)
            nmask = (mask * 3 + choice) % full
            val = gain + dp(pos + 1, nmask,
                            inn - (1 if choice == 1 else 0),
                            exn - (1 if choice == 2 else 0))
            if val > best:
                best = val
        return best

    return dp(0, 0, introvertsCount, extrovertsCount)
